#include <stdio.h>

int main(void)
{
    const char *s = "-1";
    int valid = 1;
    for (size_t i = 0; s[i] != '\0'; i++) {
        if (s[i] < '0' || s[i] > '9') { valid = 0; break; }
    }
    printf("%d\n", valid);
    return 0;
}

#include <stdio.h>

int main(void)
{
    FILE *fp = fopen("last.txt", "r");
    if (fp == NULL) { return 1; }
    int ch;
    while ((ch = fgetc(fp)) != EOF) { putchar(ch); }
    int bad = ferror(fp);
    if (fclose(fp) != 0) { bad = 1; }
    if (bad) { return 1; }
    putchar('\n');
    return 0;
}

